try {
    const keyHex = env.get("SMARTCAM_AES_KEY") || "";
    if (!/^[0-9a-fA-F]{64}$/.test(keyHex)) {
        throw new Error("Hãy đặt SMARTCAM_AES_KEY trùng với khóa hex 64 ký tự đang dùng trên camera.");
    }

    const envelope = Buffer.isBuffer(msg.payload)
        ? JSON.parse(msg.payload.toString("utf8"))
        : (typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload);
    if (!envelope || envelope.algorithm !== "AES-256-GCM" || envelope.version !== 1) {
        throw new Error("Gói cảnh báo mã hóa không hợp lệ hoặc không được hỗ trợ.");
    }

    const decipher = crypto.createDecipheriv(
        "aes-256-gcm",
        Buffer.from(keyHex, "hex"),
        Buffer.from(envelope.iv, "base64")
    );
    decipher.setAuthTag(Buffer.from(envelope.tag, "base64"));
    const plaintext = Buffer.concat([
        decipher.update(Buffer.from(envelope.ciphertext, "base64")),
        decipher.final()
    ]).toString("utf8");
    const alert = JSON.parse(plaintext);
    if (!alert.image_base64 || alert.image_mime !== "image/jpeg") {
        throw new Error("Cảnh báo không có ảnh JPEG.");
    }

    alert.imageUrl = "data:" + alert.image_mime + ";base64," + alert.image_base64;
    alert.displayTimestamp = alert.timestamp || ("Chưa đồng bộ giờ mạng (thời gian hoạt động " + (alert.uptime_ms || 0) + " ms)");
    const history = flow.get("smartcamHistory") || [];
    history.unshift(alert);
    history.length = Math.min(history.length, 10);
    flow.set("smartcamHistory", history);

    return [
        { payload: history },
        { payload: { label: alert.label, confidence: alert.confidence, timestamp: alert.displayTimestamp } }
    ];
} catch (error) {
    node.error("Từ chối cảnh báo camera: " + error.message, msg);
    return [null, { payload: "Cảnh báo bị từ chối: " + error.message }];
}
